 63	function emit(socket: Socket, event: string, payload: unknown): Promise<AckResult> {
 64	  return new Promise((resolve) => {
 65	    socket.timeout(8_000).emit(event, payload, (error: Error | null, response: AckResult) => {
 66	      resolve(error ? { ok: false, code: 'REQUEST_TIMEOUT' } : response);
 67	    });
 68	  });
 69	}
